const (
	testWaitLimit         = 3 * time.Second
	testConnectionTimeout = 100 * time.Millisecond
)

// Generated by Codex and not thoroughly checked for correctness.
func TestListenAndServeOwnsListenerAndReportsBindErrors(t *testing.T) {
	t.Run("listener is created and closed by the server package", func(t *testing.T) {
		config := defaultTimeouts()
		httpServer := server.New("127.0.0.1:0", http.NotFoundHandler(), config)
		listening := make(chan string, 1)
		httpServer.BaseContext = func(listener net.Listener) context.Context {
			listening <- listener.Addr().String()
			return context.Background()
		}
		ctx, stop := context.WithCancel(t.Context())
		defer stop()
		t.Cleanup(func() { httpServer.Close() })
		result := make(chan error, 1)
		go func() { result <- server.ListenAndServe(ctx, httpServer, config.ShutdownTimeout) }()
		var address string
		select {
		case address = <-listening:
		case err := <-result:
			t.Fatalf("startup failed: %v", err)
		case <-time.After(testWaitLimit):
			t.Fatal("listener did not start")
		}
		connection, err := net.DialTimeout("tcp", address, testWaitLimit)
		if err != nil {
			t.Fatal(err)
		}
		defer connection.Close()
		if err := connection.SetDeadline(time.Now().Add(testWaitLimit)); err != nil {
			t.Fatal(err)
		}
		writeRequest(t, connection, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n")
		response, err := http.ReadResponse(bufio.NewReader(connection), nil)
		if err != nil {
			t.Fatal(err)
		}
		response.Body.Close()
		if response.StatusCode != http.StatusNotFound {
			t.Fatalf("status=%d", response.StatusCode)
		}
		stop()
		if err := awaitResult(t, result); err != nil {
			t.Fatal(err)
		}
		if conn, err := net.DialTimeout("tcp", address, testConnectionTimeout); err == nil {
			conn.Close()
			t.Fatal("listener left open")
		}
	})
	t.Run("occupied address reports bind failure", func(t *testing.T) {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		defer listener.Close()
		httpServer := server.New(listener.Addr().String(), http.NotFoundHandler(), defaultTimeouts())
		if err := server.ListenAndServe(t.Context(), httpServer, time.Second); !errors.Is(err, syscall.EADDRINUSE) {
			t.Fatalf("listen error=%v", err)
		}
	})
}

// Generated by Codex and not thoroughly checked for correctness.
func TestShutdownWaitsForActiveRequestsWithoutCancelingThem(t *testing.T) {
	started := make(chan struct{})
	release := make(chan struct{})
	defer close(release)
	requestContext := make(chan context.Context, 1)
	fixture := startServer(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requestContext <- r.Context()
		close(started)
		<-release
		w.WriteHeader(http.StatusOK)
	}), defaultTimeouts())
	connection := fixture.connect(t)
	writeRequest(t, connection, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n")
	awaitEvent(t, started)
	ctx := <-requestContext
	fixture.stop()
	awaitEvent(t, fixture.listener.closed)
	if ctx.Err() != nil {
		t.Fatal("shutdown immediately canceled the active request")
	}
	select {
	case err := <-fixture.result:
		t.Fatalf("shutdown returned before handler completed: %v", err)
	default:
	}
	if conn, err := net.DialTimeout("tcp", fixture.address, testConnectionTimeout); err == nil {
		conn.Close()
		t.Fatal("shutdown accepted a new connection")
	}
	release <- struct{}{}
	response, err := http.ReadResponse(bufio.NewReader(connection), nil)
	if err != nil {
		t.Fatal(err)
	}
	response.Body.Close()
	if response.StatusCode != http.StatusOK {
		t.Fatalf("response=%d", response.StatusCode)
	}
	if err := awaitResult(t, fixture.result); err != nil {
		t.Fatal(err)
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestShutdownDeadlineForceClosesConnectionsAndCancelsRequests(t *testing.T) {
	started := make(chan struct{})
	finished := make(chan struct{})
	config := defaultTimeouts()
	config.ShutdownTimeout = testConnectionTimeout
	fixture := startServer(t, http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		close(started)
		<-r.Context().Done()
		close(finished)
	}), config)
	connection := fixture.connect(t)
	writeRequest(t, connection, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n")
	awaitEvent(t, started)
	fixture.stop()
	if err := awaitResult(t, fixture.result); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("shutdown error=%v", err)
	}
	awaitEvent(t, finished)
	if _, err := http.ReadResponse(bufio.NewReader(connection), nil); err == nil {
		t.Fatal("force-closed request received a response")
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestServeReportsListenerFailureAndAcceptsNormalClosure(t *testing.T) {
	t.Run("closed listener reports serving error", func(t *testing.T) {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		listener.Close()
		httpServer := server.New(listener.Addr().String(), http.NotFoundHandler(), defaultTimeouts())
		if err := server.Serve(t.Context(), httpServer, listener, time.Second); !errors.Is(err, net.ErrClosed) {
			t.Fatalf("serve error=%v", err)
		}
	})
	t.Run("external server closure is normal", func(t *testing.T) {
		fixture := startServer(t, http.NotFoundHandler(), defaultTimeouts())
		connection := fixture.connect(t)
		writeRequest(t, connection, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n")
		response, err := http.ReadResponse(bufio.NewReader(connection), nil)
		if err != nil {
			t.Fatal(err)
		}
		response.Body.Close()
		if err := fixture.server.Close(); err != nil {
			t.Fatal(err)
		}
		if err := awaitResult(t, fixture.result); err != nil {
			t.Fatal(err)
		}
	})
	t.Run("already canceled stop context closes the listener", func(t *testing.T) {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		ctx, cancel := context.WithCancel(t.Context())
		cancel()
		if err := server.Serve(ctx, server.New(listener.Addr().String(), http.NotFoundHandler(), defaultTimeouts()), listener, time.Second); err != nil {
			t.Fatal(err)
		}
		if conn, err := net.DialTimeout("tcp", listener.Addr().String(), testConnectionTimeout); err == nil {
			conn.Close()
			t.Fatal("listener left open")
		}
	})
}

// Generated by Codex and not thoroughly checked for correctness.
func TestHTTPTimeoutsBoundSlowConnections(t *testing.T) {
	for _, testCase := range []struct {
		name      string
		configure func(*configs.HTTPServerConfig)
		request   string
		handler   http.HandlerFunc
		idle      bool
	}{
		{"slow headers", func(c *configs.HTTPServerConfig) { c.ReadHeaderTimeout = testConnectionTimeout }, "GET / HTTP/1.1\r\nHost: example.test\r\n", http.NotFound, false},
		{"slow body", func(c *configs.HTTPServerConfig) { c.ReadTimeout = testConnectionTimeout }, "POST / HTTP/1.1\r\nHost: example.test\r\nContent-Length: 5\r\n\r\nx", func(w http.ResponseWriter, r *http.Request) {
			if _, err := io.ReadAll(r.Body); err != nil {
				w.WriteHeader(http.StatusRequestTimeout)
				return
			}
			w.WriteHeader(http.StatusOK)
		}, false},
		{"late response write", func(c *configs.HTTPServerConfig) { c.WriteTimeout = testConnectionTimeout }, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n", func(w http.ResponseWriter, _ *http.Request) {
			<-time.After(2 * testConnectionTimeout)
			w.WriteHeader(http.StatusOK)
		}, false},
		{"idle keep alive", func(c *configs.HTTPServerConfig) { c.IdleTimeout = testConnectionTimeout }, "GET / HTTP/1.1\r\nHost: example.test\r\n\r\n", func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) }, true},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			config := defaultTimeouts()
			testCase.configure(&config)
			fixture := startServer(t, testCase.handler, config)
			connection := fixture.connect(t)
			writeRequest(t, connection, testCase.request)
			// A missing timeout would fall back to one second. The shorter client
			// guard ensures that fallback cannot make the test pass accidentally.
			if err := connection.SetReadDeadline(time.Now().Add(5 * testConnectionTimeout)); err != nil {
				t.Fatal(err)
			}
			reader := bufio.NewReader(connection)
			response, err := http.ReadResponse(reader, nil)
			if testCase.idle {
				if err != nil {
					t.Fatal(err)
				}
				io.Copy(io.Discard, response.Body)
				response.Body.Close()
				_, err = reader.ReadByte()
			} else if err == nil {
				response.Body.Close()
				if response.StatusCode != http.StatusRequestTimeout {
					t.Fatalf("slow request status=%d", response.StatusCode)
				}
			}
			var timeout net.Error
			if errors.As(err, &timeout) && timeout.Timeout() {
				t.Fatal("server failed to close connection before client safety deadline")
			}
			if testCase.idle && err == nil {
				t.Fatal("idle connection remained open")
			}
			fixture.stop()
			if err := awaitResult(t, fixture.result); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func defaultTimeouts() configs.HTTPServerConfig {
	return configs.HTTPServerConfig{ReadHeaderTimeout: time.Second, ReadTimeout: time.Second, WriteTimeout: time.Second, IdleTimeout: time.Second, ShutdownTimeout: time.Second}
}

type serverFixture struct {
	server   *http.Server
	listener *mockNotifyingListener
	address  string
	stop     context.CancelFunc
	result   <-chan error
}

func startServer(t *testing.T, handler http.Handler, config configs.HTTPServerConfig) serverFixture {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	notifying := &mockNotifyingListener{Listener: listener, closed: make(chan struct{})}
	httpServer := server.New(listener.Addr().String(), handler, config)
	ctx, stop := context.WithCancel(t.Context())
	result := make(chan error, 1)
	go func() { result <- server.Serve(ctx, httpServer, notifying, config.ShutdownTimeout) }()
	t.Cleanup(func() { stop(); httpServer.Close() })
	return serverFixture{server: httpServer, listener: notifying, address: listener.Addr().String(), stop: stop, result: result}
}

func (fixture serverFixture) connect(t *testing.T) net.Conn {
	t.Helper()
	connection, err := net.DialTimeout("tcp", fixture.address, testWaitLimit)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { connection.Close() })
	if err := connection.SetDeadline(time.Now().Add(testWaitLimit)); err != nil {
		t.Fatal(err)
	}
	return connection
}

func writeRequest(t *testing.T, connection net.Conn, request string) {
	t.Helper()
	if _, err := fmt.Fprint(connection, request); err != nil {
		t.Fatal(err)
	}
}

func awaitEvent(t *testing.T, event <-chan struct{}) {
	t.Helper()
	select {
	case <-event:
	case <-time.After(testWaitLimit):
		t.Fatal("server event did not arrive")
	}
}

func awaitResult(t *testing.T, result <-chan error) error {
	t.Helper()
	select {
	case err := <-result:
		return err
	case <-time.After(testWaitLimit):
		t.Fatal("server did not stop")
		return nil
	}
}

type mockNotifyingListener struct {
	net.Listener
	closed chan struct{}
	once   sync.Once
}

func (listener *mockNotifyingListener) Close() error {
	err := listener.Listener.Close()
	listener.once.Do(func() { close(listener.closed) })
	return err
}
